import org.deeptimeline.app.LabelSolver
import kotlin.math.abs
fun main(){val gap=25.0;val raw=doubleArrayOf(-500.0,-150.0,0.0,1.0,2.0,3.0,350.0,700.0);var previous:DoubleArray?=null;for(step in -7000..7000){val shift=step/10.0;val anchors=DoubleArray(raw.size){raw[it]-shift};val labels=LabelSolver.solve(anchors,gap,0.0);for(i in listOf(0,1,6,7))check(abs(labels[i]-anchors[i])<1e-5){"Independent label $i bent at $shift: ${labels[i]-anchors[i]}"};for(i in 1 until labels.size)check(labels[i]-labels[i-1]>=gap-1e-7){"Labels overlap $i at $shift"};previous?.let{before->for(i in labels.indices)check(abs(labels[i]-before[i])<6.0){"Discontinuous label $i at $shift"}};previous=labels};for(index in 2..5){val shift=raw[index];val anchors=DoubleArray(raw.size){raw[it]-shift};val labels=LabelSolver.solve(anchors,gap,0.0);check(abs(labels[index])<1e-5){"Centered label $index was not straight: ${labels[index]}"}};val competing=doubleArrayOf(0.0,1.0,2.0,45.0,200.0);val pushed=LabelSolver.solve(competing,gap,0.0);check(pushed[3]>competing[3]);check(abs(pushed[4]-competing[4])<1e-5);val released=LabelSolver.solve(competing,gap,45.0);check(abs(released[3]-competing[3])<1e-5);check(abs(released[4]-competing[4])<1e-5);println("Locality: isolated connectors remain straight, adjacent push/release, center continuity: PASS")}
